class Tally:
    def __init__(self):
        self.total = 0

    def value(self) -> int:
        """Return the sum of all increments minus all decrements."""
        return self.total

    def increment(self, count: int) -> None:
        """Increment the total by a certain count."""
        self.total += count

    def decrement(self, count: int) -> None:
        """Decrement the total by a certain count."""
        self.total -= count

    def merge(self, other: "Tally") -> None:
        """Merge another Tally object into this one by adding the totals."""
        self.total += other.value()

