class Job:
    def __init__(self, name, dependencies=None, should_fail=False):
        self.name = name
        self.dependencies = dependencies if dependencies is not None else []
        self.should_fail = should_fail

    def run(self):
        if self.should_fail:
            raise Exception(f"Job {self.name} failed intentionally.")
        print(f"Job {self.name} completed successfully.")

class JobNet:
    def __init__(self, jobs=None):
        self.jobs = jobs if jobs is not None else []

    def add_job(self, job):
        self.jobs.append(job)

    def run_jobs(self):
        completed_jobs = set()
        while self.jobs:
            for job in list(self.jobs):
                if all(dep in completed_jobs for dep in job.dependencies):
                    try:
                        job.run()
                        completed_jobs.add(job.name)
                    except Exception as e:
                        print(e)
                    self.jobs.remove(job)

