from datetime import datetime, timedelta

class SlotBook:
    def __init__(self):
        self.bookings = []

    def book_slot(self, start: datetime, end: datetime, repeat_weekly=False):
        self.bookings.append({'start': start, 'end': end, 'repeat_weekly': repeat_weekly})

    def resolve_dst(self, dt: datetime) -> datetime:
        try:
            return dt.replace(hour=dt.hour + 1)
        except ValueError:
            return dt + timedelta(hours=1)

    def get_bookings(self):
        current_time = datetime.utcnow()
        resolved_bookings = []
        for booking in self.bookings:
            start = booking['start']
            end = booking['end']
            if booking['repeat_weekly']:
                while start < current_time:
                    start += timedelta(weeks=1)
                    end += timedelta(weeks=1)
            resolved_bookings.append({'start': self.resolve_dst(start), 'end': self.resolve_dst(end)})
        return resolved_bookings

