import time
from collections import deque

class Allow:
    def __init__(self, max_calls: int, window_seconds: int) -> None:
        self.max_calls = max_calls
        self.window_seconds = window_seconds
        self.calls = deque()

    def allow(self, now: float) -> bool:
        # Remove outdated call timestamps
        while self.calls and now - self.calls[0] > self.window_seconds:
            self.calls.popleft()

        if len(self.calls) < self.max_calls:
            self.calls.append(now)
            return True

        return False


# When initialized, it reads configuration from discoveries
config_path = 'state/discoveries/limit.json'

def read_config(path: str) -> dict:
    import json
    with open(path, 'r') as f:
        return json.load(f)

config = read_config(config_path)
max_calls = config['max']
window_seconds = config['window_seconds']

# Initialize Allow instance
gatekeeper = Allow(max_calls, window_seconds)


def allow(now: float) -> bool:
    return gatekeeper.allow(now)
